<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  0000020</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 04000004</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 04000000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 00000000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 00000000</span></span>
